-- profiler_questions_seed.sql
-- Creates the Profiler question table and seeds a starter pool of 65 questions.
--
-- SAFE TO RE-RUN: the table is only created if it doesn't exist yet, and every
-- insert skips a question whose exact text is already in the table. Running it
-- twice adds nothing the second time.
--
-- How Profiler uses this table:
--   * Each round, everyone privately picks one option on their phone.
--   * The TV then shows ONE answer someone gave ("2 of you said: Gentle truth")
--     and everyone guesses who said it.
--   * option_a and option_b are required. option_c through option_g are
--     optional -- leave them NULL for a question with fewer choices (2 to 7).
--   * intensity: 1 = light and silly, 2 = says something about you,
--                3 = deeper (moral / metaphysical). The game mixes them so it
--                never stays heavy for long.
--   * active = false hides a question without deleting it.
--
-- THE CONTENT RULE: every option must be one a person would comfortably own out
-- loud, in front of family, on the TV. No confessions, no "wrong" answers.
-- Off-limits topics: politics, religion as identity, sex/dating, bodies/weight,
-- money amounts, health, family conflict, and questions about people in the room.

CREATE TABLE IF NOT EXISTS profiler_questions (
    id            SERIAL PRIMARY KEY,
    question_text TEXT NOT NULL UNIQUE,
    category      TEXT NOT NULL,          -- HYPOTHETICAL / PERSONALITY / VALUES / LIGHT / BIG_QUESTIONS
    intensity     SMALLINT NOT NULL CHECK (intensity BETWEEN 1 AND 3),
    option_a      TEXT NOT NULL,
    option_b      TEXT NOT NULL,
    option_c      TEXT,
    option_d      TEXT,
    option_e      TEXT,
    option_f      TEXT,
    option_g      TEXT,
    active        BOOLEAN NOT NULL DEFAULT true
);

